import unittest

from solution import count_payloads


class CountPayloadsTests(unittest.TestCase):
    def test_normal_nested_catalog_and_zero(self):
        catalog = {
            "first": [0, 5, {"nested": 8}],
            "empty_dict": {},
            "empty_list": [],
        }
        self.assertEqual(count_payloads(catalog), 3)
        self.assertEqual(catalog, {
            "first": [0, 5, {"nested": 8}],
            "empty_dict": {},
            "empty_list": [],
        })

    def test_empty_containers(self):
        self.assertEqual(count_payloads({}), 0)
        self.assertEqual(count_payloads([]), 0)

    def test_shared_container_is_counted_per_occurrence(self):
        shared = [1, {"x": 2}]
        self.assertEqual(count_payloads([shared, shared]), 4)

    def test_direct_and_indirect_cycles_raise_value_error(self):
        direct = []
        direct.append(direct)
        with self.assertRaises(ValueError):
            count_payloads(direct)

        outer = {}
        inner = [outer]
        outer["loop"] = inner
        with self.assertRaises(ValueError):
            count_payloads(outer)

    def test_malformed_leaves_raise_type_error(self):
        malformed = [True, -1, "3", None, 1.5, object()]
        for value in malformed:
            with self.subTest(value=repr(value)):
                with self.assertRaises(TypeError):
                    count_payloads([value])

    def test_dictionary_keys_must_be_strings(self):
        with self.assertRaises(TypeError):
            count_payloads({1: 4})
        with self.assertRaises(TypeError):
            count_payloads({False: []})

    def test_dictionary_insertion_order_does_not_change_result(self):
        first = {"a": [1, 2], "b": {"c": 3}}
        second = {"b": {"c": 3}, "a": [1, 2]}
        self.assertEqual(count_payloads(first), 3)
        self.assertEqual(count_payloads(second), 3)


if __name__ == "__main__":
    unittest.main()

